package com.smartseating.ui;

import com.smartseating.dao.*;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.List;

public class StudentFrame extends AppFrame {
    private final StudentDAO dao=new StudentDAO(); private final DepartmentDAO departmentDAO=new DepartmentDAO(); private final SemesterDAO semesterDAO=new SemesterDAO();
    private final JTextField reg=new JTextField(),name=new JTextField(),division=new JTextField("A"),search=new JTextField(); private final JComboBox<Department> dept=new JComboBox<>(); private final JComboBox<Semester> sem=new JComboBox<>(); private final JComboBox<String> status=new JComboBox<>(new String[]{"ACTIVE","INACTIVE"}); private final JTable table=new JTable(); private Student selected;
    public StudentFrame(User user){super("Student Management",user);UI.frame(this,1120,680);build();refresh();}
    private void build(){content.add(title("Student Management"),BorderLayout.NORTH);JPanel left=UI.formPanel();UI.addField(left,0,"Register Number",reg);UI.addField(left,1,"Student Name",name);UI.addField(left,2,"Department",dept);UI.addField(left,3,"Semester",sem);UI.addField(left,4,"Division",division);UI.addField(left,5,"Status",status);JPanel actions=new JPanel(new GridLayout(2,3,7,7));actions.setOpaque(false);JButton add=button("ADD",UI.TEAL),update=button("UPDATE",UI.BLUE),del=button("DELETE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);actions.add(add);actions.add(update);actions.add(del);actions.add(clear);actions.add(print);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=6;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);left.add(actions,g);content.add(white(left),BorderLayout.WEST);
        JPanel right=new JPanel(new BorderLayout(8,8));right.setOpaque(false);JPanel searchPanel=new JPanel(new BorderLayout(8,0));searchPanel.setBackground(Color.WHITE);searchPanel.setBorder(BorderFactory.createEmptyBorder(5,5,5,5));searchPanel.add(new JLabel("Search register, name, department or semester"),BorderLayout.WEST);searchPanel.add(search,BorderLayout.CENTER);JButton go=button("SEARCH",UI.BLUE);searchPanel.add(go,BorderLayout.EAST);right.add(searchPanel,BorderLayout.NORTH);UI.tableStyle(table);right.add(UI.scroll(table),BorderLayout.CENTER);content.add(right,BorderLayout.CENTER);
        add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());go.addActionListener(e->refresh());print.addActionListener(e->PrintService.print("Student List",tableText()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)loadSelected();});try{dept.removeAllItems();for(Department d:departmentDAO.findAll())dept.addItem(d);for(Semester s:semesterDAO.findAll())sem.addItem(s);}catch(Exception ex){error(ex);}if("TEACHER".equals(userRole())){add.setEnabled(false);update.setEnabled(false);del.setEnabled(false);}}
    private String userRole(){return currentUser==null?"":currentUser.getRole();}
    private void save(){try{Student s=read();dao.save(s);clear();refresh();}catch(Exception ex){error(ex);}}
    private void update(){try{if(selected==null)throw new IllegalArgumentException("Select a student first.");Student s=read();s.setId(selected.getId());dao.update(s);clear();refresh();}catch(Exception ex){error(ex);}}
    private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a student first.");if(confirm("Delete selected student?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}
    private Student read(){Department d=(Department)dept.getSelectedItem();Semester s=(Semester)sem.getSelectedItem();Student x=new Student(0,Validation.text(reg.getText(),"Register number"),Validation.text(name.getText(),"Student name"),d==null?"":d.getCode(),s==null?"":s.getNumber(),Validation.text(division.getText(),"Division"),(String)status.getSelectedItem());if(x.getDepartmentCode().isBlank()||x.getSemesterNumber().isBlank())throw new IllegalArgumentException("Department and semester are required.");return x;}
    private void loadSelected(){int r=table.getSelectedRow();selected=new Student((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,2)),String.valueOf(table.getValueAt(r,3)),String.valueOf(table.getValueAt(r,4)),String.valueOf(table.getValueAt(r,5)),String.valueOf(table.getValueAt(r,6)));reg.setText(selected.getRegisterNumber());name.setText(selected.getName());division.setText(selected.getDivision());status.setSelectedItem(selected.getStatus());for(int i=0;i<dept.getItemCount();i++)if(dept.getItemAt(i).getCode().equals(selected.getDepartmentCode()))dept.setSelectedIndex(i);for(int i=0;i<sem.getItemCount();i++)if(sem.getItemAt(i).getNumber().equals(selected.getSemesterNumber()))sem.setSelectedIndex(i);}
    private void clear(){selected=null;reg.setText("");name.setText("");division.setText("A");status.setSelectedIndex(0);table.clearSelection();}
    private void refresh(){try{List<Student> list=dao.search(search.getText());DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Register No","Name","Dept","Semester","Division","Status"},0);for(Student s:list)m.addRow(new Object[]{s.getId(),s.getRegisterNumber(),s.getName(),s.getDepartmentCode(),s.getSemesterNumber(),s.getDivision(),s.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}
    private String tableText(){StringBuilder b=new StringBuilder("STUDENT LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | ").append(table.getValueAt(i,3)).append(" | ").append(table.getValueAt(i,4)).append("\n");return b.toString();}
}
